    var stim = function (id) { var s = (p.stimuli || {})[id]; if (!s) return null; return s.type === 'image' ? '<figure class="p1stim" style="margin:0"><img src="' + esc(s.src) + '" alt="' + esc(s.alt) + '" loading="lazy" style="max-width:100%;height:auto;background:#fff"><figcaption class="hint">' + esc(s.caption || '') + '</figcaption></figure>' : (s.html || ''); };
